<?php use function KB\{e,url}; $settings=json_decode($attempt['settings_snapshot'],true); ?><section class="page-heading"><div><span class="eyebrow">ANOTHER STEP FORWARD</span><h1><?= $attempt['percentage']>=$settings['pass_mark']?'Well done. Keep growing.':'Every step is a chance to learn.' ?></h1><p>Your answers have been saved. Take a moment to reflect on what you’ve learned.</p></div><a class="button" href="<?= e(url('dashboard')) ?>">Back to your dashboard →</a></section><section class="result-summary"><div><strong><?= (int)$attempt['score'] ?><small> / <?= (int)$attempt['total_questions'] ?></small></strong><span>Correct answers</span></div><div><strong><?= e($attempt['percentage']) ?>%</strong><span>Your score</span></div><div><span class="badge <?= $attempt['percentage']>=$settings['pass_mark']?'green':'neutral' ?>"><?= $attempt['percentage']>=$settings['pass_mark']?'Passed':'Keep growing' ?></span><span>Pass mark: <?= (int)$settings['pass_mark'] ?>%</span></div></section><section class="stack"><?php foreach($items as $i=>$item): ?><article class="panel review-item"><div class="section-heading"><span class="eyebrow">QUESTION <?= $i+1 ?></span><span class="badge <?= $item['answer']!==null && (int)$item['answer']===(int)$item['correct_option']?'green':'neutral' ?>"><?= $item['answer']!==null && (int)$item['answer']===(int)$item['correct_option']?'Correct':($item['answer']===null?'Unanswered':'Review') ?></span></div><h2><?= e($item['question_text']) ?></h2><div class="review-options"><?php foreach(json_decode($item['options_snapshot'],true) as $j=>$option): ?><div class="<?= $j===(int)$item['correct_option']?'correct':($j===$item['answer']?'incorrect':'') ?>"><span><?= chr(65+$j) ?></span><?= e($option) ?> <?php if($j===(int)$item['correct_option']): ?><small>Correct answer</small><?php elseif($j===$item['answer']): ?><small>Your answer</small><?php endif; ?></div><?php endforeach; ?></div><p class="muted"><?= e($item['reference']) ?><?= $item['explanation']?' · '.e($item['explanation']):'' ?></p></article><?php endforeach; ?></section>
